 @page "/notepad"
 @rendermode InteractiveServer
 @inject IJSRuntime JS
 @implements IAsyncDisposable

 <PageTitle>Notepad</PageTitle>

 <h1>Notepad</h1>

 <textarea value="@Content" @oninput="OnInputAsync" rows="12" class="notepad-textarea"></textarea>

 <div class="notepad-controls">
     <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
     <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
     @if (_lastSaved is not null)
     {
         <span class="notepad-status">Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</span>
     }
 </div>

 @code {
     private string Content { get; set; } = string.Empty;
     private string _savedContent = string.Empty;
     private DateTime? _lastSaved;
     private NotepadInterop? _interop;
     private DotNetObjectReference<Notepad>? _dotNetRef;
     private Timer? _autoSaveTimer;

     private bool IsDirty => Content != _savedContent;

     private async Task OnInputAsync(ChangeEventArgs e)
     {
         Content = e.Value?.ToString() ?? string.Empty;
         if (_interop is not null && IsDirty)
             await _interop.SetDirtyAsync(true);
     }

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             _interop = new NotepadInterop(JS);
             _dotNetRef = DotNetObjectReference.Create(this);
             await _interop.InitializeAsync(_dotNetRef);

             var stored = await _interop.LoadAsync();
             if (stored is not null)
             {
                 Content = stored;
                 _savedContent = stored;
                 StateHasChanged();
             }

             _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
         }
     }

     private async void AutoSaveCallback(object? state)
     {
         await InvokeAsync(async () =>
         {
             if (IsDirty)
             {
                 await PerformSaveAsync();
                 StateHasChanged();
             }
         });
     }

     private async Task SaveNowAsync()
     {
         await PerformSaveAsync();
     }

     private async Task PerformSaveAsync()
     {
         if (_interop is null) return;

         await _interop.SaveAsync(Content);
         _savedContent = Content;
         _lastSaved = DateTime.Now;
         await _interop.SetDirtyAsync(false);
     }

     private async Task ClearAsync()
     {
         if (_interop is null) return;

         Content = string.Empty;
         _savedContent = string.Empty;
         _lastSaved = null;
         await _interop.ClearAsync();
         await _interop.SetDirtyAsync(false);
     }

     public async ValueTask DisposeAsync()
     {
         _autoSaveTimer?.Dispose();

         if (_interop is not null)
             await _interop.DisposeAsync();

         _dotNetRef?.Dispose();
     }
 }
